---@class BTParallelNode
local BTParallelNode = Class('BTParallelNode', BTNode)
function BTParallelNode:__init(...)
    local t = {...}
    local threshold = #t > 1 and table.remove(t, 1) or 1
    self._threshold = threshold

    BTNode.__init(self, SafeUnpack(t)) 
