function BTParallelNode:OnUpdate(agent, blackboard)
    local childCount = BTNode.GetChildCount(self)
    if childCount == 0 then
        return BTNode.BTStatus.FINISHED
    end

    local threshold = self._threshold
    local failedCount   = 0
    local finishedCount = 0
    for i = 1, childCount do
        ---@type BTNode
        local child = BTNode.GetChild(self, i)
        local status = child:Update(agent, blackboard)
        if status == BTNode.BTStatus.FINISHED then
            finishedCount = finishedCount + 1
            if finishedCount == threshold then
                return BTNode.BTStatus.FINISHED
            end
        elseif status == BTNode.BTStatus.FAILED then
            failedCount = failedCount + 1
            if failedCount == childCount - threshold then
                return BTNode.BTStatus.FAILED
            end
        end
    end
    
    return BTNode.BTStatus.EXECUTING
    
end

function BTParallelNode:OnReset(agent, blackboard)
    local childCount = BTNode.GetChildCount(self)
    for i = 1, childCount do
        ---@type BTNode
        local child = BTNode.GetChild(self, i)
        child:Reset(agent, blackboard)
    end
    
end


